export const SimpleIcon = ({
  icon,
  style,
  className,
  ...props
}: IconProps & { icon: SimpleIconType }) => {
  return (
    <svg
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill={"currentColor"}
      style={{ "--accent": `#${icon.hex}`, ...style } as React.CSSProperties}
      className={cn("text-accent", className)}
      {...props}
    >
      <title>{icon.title}</title>
      <path d={icon.path} />
    </svg>
  );
};

